plugins {
    id 'java'
    // bootRun / bootJar 태스크 제공 + 실행 가능한 fat jar 패키징
    id 'org.springframework.boot' version '4.1.1'
    // Boot BOM을 적용해서 아래 의존성들의 버전을 생략할 수 있게 해줌
    id 'io.spring.dependency-management' version '1.1.7'
}

group = 'org.example'
version = '1.0-SNAPSHOT'

java {
    toolchain {
        // 컴파일·실행 JDK를 고정 (Boot 4는 Java 17 이상 필요, 로컬에 설치된 21 사용)
        languageVersion = JavaLanguageVersion.of(21)
    }
}

repositories {
    mavenCentral()
}

dependencies {
    compileOnly 'org.projectlombok:lombok'
    annotationProcessor 'org.projectlombok:lombok'
    // Spring MVC + 내장 Tomcat + Jackson (Boot 4부터 starter-web → starter-webmvc로 이름 변경)
    implementation 'org.springframework.boot:spring-boot-starter-webmvc'
    // JPA(Hibernate) + HikariCP 커넥션 풀
    implementation 'org.springframework.boot:spring-boot-starter-data-jpa'
    implementation 'org.mybatis.spring.boot:mybatis-spring-boot-starter:4.1.0'
    // @Valid, @NotBlank 같은 요청 값 검증
    implementation 'org.springframework.boot:spring-boot-starter-validation'
    // MySQL JDBC 드라이버 — 컴파일엔 필요 없고 실행할 때만 필요
    runtimeOnly 'com.mysql:mysql-connector-j'

    // 테스트: JUnit·AssertJ·Mockito·MockMvc 묶음 (버전은 Boot BOM이 관리하므로 junit-bom 따로 두지 않음)
    testImplementation 'org.springframework.boot:spring-boot-starter-webmvc-test'
    // @DataJpaTest(리포지토리만 띄우는 테스트)
    testImplementation 'org.springframework.boot:spring-boot-starter-data-jpa-test'
    // 테스트용 일회용 MySQL 컨테이너 — application-test.yml의 jdbc:tc: URL이 쓴다
    testImplementation 'org.testcontainers:testcontainers-mysql'
    // Gradle이 JUnit Platform 테스트를 실행할 때 필요한 런처
    testRuntimeOnly 'org.junit.platform:junit-platform-launcher'
}

tasks.named('test') {
    useJUnitPlatform()
    // 테스트는 application-test.yml(Testcontainers MySQL)을 쓰게 한다
    systemProperty 'spring.profiles.active', 'test'
}

package org.example.post;

import jakarta.validation.Valid;
import org.slf4j.Logger;
import org.slf4j.LoggerFactory;
import org.springframework.http.ResponseEntity;
import org.springframework.web.bind.annotation.PostMapping;
import org.springframework.web.bind.annotation.RequestBody;
import org.springframework.web.bind.annotation.RequestMapping;
import org.springframework.web.bind.annotation.RestController;

import java.net.URI;

@RestController
@RequestMapping("/api/posts")
public class PostController {

    private static final Logger log = LoggerFactory.getLogger(PostController.class);

    private final PostService postService;

    public PostController(PostService postService) {
        this.postService = postService;
    }

    @PostMapping
    public ResponseEntity<PostResponse> create(@Valid @RequestBody PostCreateRequest request) {
        log.info("게시글 작성 요청 제목: {}", request.title());

        PostResponse response = postService.create(request);

        return ResponseEntity.created(URI.create("/api/posts/" + response.id())).body(response);
    }

}

package org.example.post;

import org.example.board.BoardNotFoundException;
import org.example.board.BoardWriteForbiddenException;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;

import java.time.LocalDateTime;
import java.util.LinkedHashMap;
import java.util.LinkedHashSet;
import java.util.List;
import java.util.Map;
import java.util.Set;

// 게시판·작성자 확인부터 글·태그 연결까지 Mapper SQL로 실행한다.
@Service
public class PostService {
    private static final long FIXED_AUTHOR_ID = 2L;
    private static final String ADMIN_ROLE = "ADMIN";
    private static final String DEFAULT_VISIBILITY = "PUBLIC";
    private final PostCreationMapper mapper;

    public PostService(PostCreationMapper mapper) {
        this.mapper = mapper;
    }

    @Transactional
    public PostResponse create(PostCreateRequest request) {
        BoardWriteRow board = mapper.findBoardBySlug(request.boardSlug());
        if (board == null) {
            throw new BoardNotFoundException(request.boardSlug());
        }
        // 로그인 도입 전이므로 작성자는 고정 회원이다. 1-6에서 토큰 주인으로 바꾼다.
        AuthorWriteRow author = mapper.findAuthorById(FIXED_AUTHOR_ID);
        if (author == null) {
            throw new IllegalStateException("인증된 작성자를 찾을 수 없습니다.");
        }
        if (ADMIN_ROLE.equals(board.writeRole) && !ADMIN_ROLE.equals(author.role)) {
            throw new BoardWriteForbiddenException(board.slug);
        }

        PostInsert post = new PostInsert();
        post.boardId = board.id;
        post.authorId = author.id;
        post.title = request.title();
        post.content = request.content();
        post.visibility = request.visibility() == null ? DEFAULT_VISIBILITY : request.visibility();
        post.now = LocalDateTime.now();
        mapper.insertPost(post);

        Map<Long, String> storedTags = new LinkedHashMap<>();
        for (String tagName : distinctTagNames(request.tags())) {
            mapper.insertTagIfAbsent(tagName, post.now);
            TagWriteRow tag = mapper.findTagByName(tagName);
            if (!storedTags.containsKey(tag.id)) {
                mapper.linkTag(post.id, tag.id);
                storedTags.put(tag.id, tag.name);
            }
        }
        return new PostResponse(post.id, board.slug, post.title, post.content,
                List.copyOf(storedTags.values()), post.visibility,
                new AuthorResponse(author.id, author.nickname), post.now);
    }

    private List<String> distinctTagNames(List<String> tags) {
        if (tags == null) {
            return List.of();
        }
        Set<String> seen = new LinkedHashSet<>(tags);
        return List.copyOf(seen);
    }
}

package org.example.post;

// 게시판 쓰기 권한 검사에 필요한 컬럼만 읽는다.
public class BoardWriteRow {
    public Long id;
    public String slug;
    public String writeRole;
}

package org.example.post;

// 작성자 ID는 인증된 토큰에서 받고, 닉네임·역할은 DB에서 확인한다.
public class AuthorWriteRow {
    public Long id;
    public String nickname;
    public String role;
}

package org.example.post;

import java.time.LocalDateTime;

// MyBatis가 INSERT 후 생성 키를 id에 채운다.
public class PostInsert {
    public Long id;
    public Long boardId;
    public Long authorId;
    public String title;
    public String content;
    public String visibility;
    public LocalDateTime now;
}

package org.example.post;

// DB에 저장된 태그의 정규 이름을 응답에 사용한다.
public class TagWriteRow {
    public Long id;
    public String name;
}

package org.example.post;

import java.time.LocalDateTime;
import org.apache.ibatis.annotations.Mapper;
import org.apache.ibatis.annotations.Param;

@Mapper
public interface PostCreationMapper {
    BoardWriteRow findBoardBySlug(@Param("slug") String slug);
    AuthorWriteRow findAuthorById(@Param("id") Long id);
    int insertPost(PostInsert post);
    int insertTagIfAbsent(@Param("name") String name, @Param("now") LocalDateTime now);
    TagWriteRow findTagByName(@Param("name") String name);
    int linkTag(@Param("postId") Long postId, @Param("tagId") Long tagId);
}
